.tf-cg-bottom-bar {
  position: fixed;
  bottom: 0;
  left: 0;
  width: 360px;
  height: 64px;
  background-color: var(--color-bg-card);
  display: flex;
  align-items: center;
  padding: 0 var(--spacing-lg);
  gap: var(--spacing-lg);
  box-shadow: 0 -2px 8px 0 rgba(0, 0, 0, 0.06);
  box-sizing: border-box;
}

.tf-cg-bottom-bar__icons {
  display: flex;
  align-items: center;
  gap: var(--spacing-md);
  flex-shrink: 0;
}

.tf-cg-bottom-bar__icon-btn {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 2px;
  background: none;
  border: none;
  padding: var(--spacing-xs);
  cursor: pointer;
  border-radius: var(--radius-xxs);
  min-width: 40px;
}

.tf-cg-bottom-bar__icon-btn:active {
  background-color: var(--color-bg-hover);
}

.tf-cg-bottom-bar__icon-label {
  color: var(--color-text-secondary);
  margin-top: 1px;
}

.tf-cg-bottom-bar__actions {
  display: flex;
  flex: 1;
  gap: var(--spacing-md);
  height: 40px;
}

.tf-cg-bottom-bar__btn {
  flex: 1;
  height: 40px;
  border-radius: var(--radius-full);
  border: none;
  cursor: pointer;
  display: flex;
  align-items: center;
  justify-content: center;
  transition: opacity 150ms ease;
}

.tf-cg-bottom-bar__btn:active {
  opacity: 0.85;
}

.tf-cg-bottom-bar__btn--secondary {
  background-color: var(--color-primary-soft);
  color: var(--color-primary);
  border: 1px solid var(--color-primary-disabled);
}

.tf-cg-bottom-bar__btn--primary {
  background-color: var(--color-primary);
  color: var(--color-text-white);
}

