.tf-cg-sheet-overlay {
  position: fixed;
  inset: 0;
  display: flex;
  align-items: flex-end;
  justify-content: center;
  background-color: var(--color-mask);
}

.tf-cg-sheet {
  width: 100%;
  max-width: 360px;
  background-color: var(--color-bg-card);
  border-radius: var(--radius-2xl) var(--radius-2xl) 0 0;
  display: flex;
  flex-direction: column;
  max-height: 80vh;
  box-shadow: var(--shadow-lg);
}

.tf-cg-sheet-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: var(--spacing-xl) var(--spacing-xl) var(--spacing-lg);
  border-bottom: 1px solid var(--color-divider-subtle);
}

.tf-cg-sheet-header-actions {
  display: flex;
  align-items: center;
  gap: var(--spacing-lg);
}

.tf-cg-clear-text {
  color: var(--color-text-secondary);
  cursor: pointer;
}

.tf-cg-close-btn {
  background: none;
  border: none;
  padding: 0;
  color: var(--color-text-secondary);
  cursor: pointer;
  display: flex;
  align-items: center;
}

.tf-cg-sheet-body {
  flex: 1;
  overflow-y: auto;
  padding: var(--spacing-lg) var(--spacing-xl);
  display: flex;
  flex-direction: column;
  gap: var(--spacing-lg);
}

.tf-cg-warning {
  display: flex;
  align-items: center;
  gap: var(--spacing-md);
  padding: var(--spacing-md) var(--spacing-lg);
  background-color: rgba(249, 115, 22, 0.08);
  border-radius: var(--radius-md);
  color: var(--color-text-primary);
}

.tf-cg-warning svg {
  color: var(--color-warning);
  flex-shrink: 0;
}

.tf-cg-product {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: var(--spacing-lg) 0;
  border-bottom: 1px solid var(--color-divider-faint);
}

.tf-cg-product-info {
  display: flex;
  flex-direction: column;
  gap: var(--spacing-xs);
}

.tf-cg-product-name {
  color: var(--color-text-primary);
}

.tf-cg-product-qty {
  color: var(--color-text-secondary);
}

.tf-cg-product-price {
  color: var(--color-text-primary);
}

.tf-cg-entry {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: var(--spacing-lg) 0;
  color: var(--color-text-primary);
}

.tf-cg-entry-info {
  display: flex;
  flex-direction: column;
  gap: var(--spacing-xs);
}

.tf-cg-entry-sub {
  color: var(--color-text-secondary);
}

.tf-cg-sheet-footer {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: var(--spacing-lg) var(--spacing-xl);
  border-top: 1px solid var(--color-divider-subtle);
  background-color: var(--color-bg-card);
}

.tf-cg-total {
  display: flex;
  align-items: baseline;
}

.tf-cg-total-price {
  color: var(--color-primary);
  font-weight: var(--font-weight-bold);
}

.tf-cg-primary-btn {
  background-color: var(--color-primary);
  color: var(--color-text-white);
  border: none;
  border-radius: var(--radius-full);
  padding: var(--spacing-md) var(--spacing-2xl);
  cursor: pointer;
  min-width: 100px;
  text-align: center;
}

