}

/* ============================================
   页面转场动画
   ============================================ */

@keyframes slide-in-right {
  from { transform: translateX(100%); }
  to   { transform: translateX(0); }
}
@keyframes slide-out-right {
  from { transform: translateX(0); }
  to   { transform: translateX(100%); }
}
@keyframes fade-in {
  from { opacity: 0; }
  to   { opacity: 1; }
}
@keyframes slide-up {
  from { transform: translateY(100%); }
  to   { transform: translateY(0); }
}
@keyframes page-in {
  from { opacity: 0; }
  to   { opacity: 1; }
}

.animate-slide-in-right { animation: slide-in-right 300ms ease-out forwards; }
.animate-slide-out-right { animation: slide-out-right 300ms ease-in forwards; }
.fade-in { animation: fade-in 300ms ease-out forwards; }
.animate-slide-up { animation: slide-up 300ms ease-out forwards; }
.animate-page-in { animation: page-in 150ms ease-out; }

.tf-cg-mask {
  position: absolute;
  inset: 0;
  background-color: var(--color-mask);
}

.tf-cg-sheet {
  position: absolute;
  bottom: 0;
  left: 0;
  right: 0;
  background-color: var(--color-bg-card);
  border-top-left-radius: var(--radius-xl);
  border-top-right-radius: var(--radius-xl);
  display: flex;
  flex-direction: column;
  box-shadow: var(--shadow-lg);
  animation: slide-up 300ms ease-out forwards;
}

.tf-cg-header {
  display: flex;
  align-items: center;
  justify-content: center;
  position: relative;
  padding: var(--spacing-xl);
  border-bottom: 1px solid var(--color-divider-subtle);
}

.tf-cg-title {
  color: var(--color-text-primary);
}

.tf-cg-close-btn {
  position: absolute;
  right: var(--spacing-xl);
  top: 50%;
  transform: translateY(-50%);
  background: transparent;
  border: none;
  color: var(--color-text-secondary);
  padding: var(--spacing-xs);
  display: flex;
  align-items: center;
  justify-content: center;
  cursor: pointer;
}

.tf-cg-body {
  padding: var(--spacing-xl);
  flex: 1;
}

.tf-cg-field {
  display: flex;
  flex-direction: column;
  gap: var(--spacing-md);
}

.tf-cg-label {
  color: var(--color-text-primary);
  font-weight: var(--font-weight-medium);
}

.tf-cg-input-wrapper {
  background-color: var(--color-bg-page);
  border-radius: var(--radius-md);
  padding: var(--spacing-lg) var(--spacing-xl);
  border: 1px solid var(--color-border-subtle);
}

.tf-cg-input {
  width: 100%;
  background: transparent;
  border: none;
  outline: none;
  color: var(--color-text-primary);
}

.tf-cg-input::placeholder {
  color: var(--color-text-hint);
}

.tf-cg-footer {
  padding: var(--spacing-lg) var(--spacing-xl);
  padding-bottom: calc(var(--spacing-xl) + env(safe-area-inset-bottom, 0px));
}

.tf-cg-primary-btn {
  width: 100%;
  background-color: var(--color-primary);
  color: var(--color-text-white);
  border: none;
  border-radius: var(--radius-full);
  padding: var(--spacing-lg) 0;
  cursor: pointer;
  text-align: center;
}

